promql:
histogram_quantile(
  0.90,
  sum(
    rate(
      traces_service_graph_request_server_seconds_bucket{
        service="auth",
        client="TS"
      }[1h]
    )
  ) by (le)
)

(
  node_sockstat_TCP_tw / node_sockstat_TCP_alloc
) - (
  node_sockstat_TCP_tw offset 1d / node_sockstat_TCP_alloc offset 1d
)

topk(1,
  sum by (instance) (
    rate(node_cpu_seconds_total{mode="user"}[1m]) + rate(node_cpu_seconds_total{mode="system"}[1m])
  )
  and
  node_load1 < 0.8
  and
  {service="gateway"}
)

topk(3, 
  predict_linear(
    node_filesystem_avail_bytes{instance=~"10.176.122.15[0-9]:.*", mountpoint="/"}[1w], 
    7*24*60*60
  ) / 1e9
  on(instance) group_left(node_filesystem_avail_bytes)
  node_filesystem_avail_bytes{instance=~"10.176.122.15[0-9]:.*", mountpoint="/"}
)

histogram_quantile(
  0.5,
  sum(
    rate(traces_spanmetrics_latency_bucket{service="admin-order-service"}[5m])
  ) by (le)
) - on() group_left()
histogram_quantile(
  0.5,
  sum(
    rate(traces_spanmetrics_latency_bucket{service="admin-order-service", le="0.01"}[5m])
  ) by (le)
)

sum by (mode, instance) (
  rate(node_cpu_seconds_total{instance=~"10.176.122.15[1-3]:.*"}[1m])
) / on (instance) machine_cpu_cores > bool 16

sum(
  increase(
    container_network_receive_errors_total{interface="eth0", service="admin user service"}[1h]
  )
)
sum(
  increase(
    container_network_receive_errors_total{interface="eth0", pod=~"admin user service.*"}[1h]
  )
)

histogram_quantile(
  0.8,
  sum(
    rate(
      traces_service_graph_request_client_seconds_bucket{
        client="auth",
        server="verification code"
      }[5m]
    )
  ) by (le)
)
